"""Blender (read-only): the terrain scatter (grass, flowers, small plants generated by geometry nodes on the terrain).
  blender -b --factory-startup --disable-autoexec <file.blend> --python export_scatter.py -- <out_dir> [x0 y0 x1 y1]
Walks the evaluated dependency graph and collects every instance whose parent is a Terrain_* object.
Writes <out_dir>/scatter.json  (per source object: mesh name, materials, triangle count, instance count)
       <out_dir>/scatter_<n>.npy  float32 (instances, 12): row-major 3x4 world matrices, for source object n
       <out_dir>/scatter_mesh_<n>.npz  pos, loop_vert, loop_normal, uv0, tri_loops, tri_mat of the source mesh
Optional bounds (metres) keep only instances inside that XY rectangle."""
import bpy, sys, json, os
import numpy as np

args = sys.argv[sys.argv.index("--") + 1:]
out = args[0]; os.makedirs(out, exist_ok=True)
bounds = [float(v) for v in args[1:5]] if len(args) >= 5 else None
diag = {}
for ob_ in bpy.data.objects:
    if ob_.name.startswith("Terrain"):
        for md in ob_.modifiers:
            diag.setdefault(ob_.name, []).append({"name": md.name, "type": md.type, "show_viewport": md.show_viewport, "show_render": md.show_render,
                                                  "group": md.node_group.name if md.type == "NODES" and md.node_group else None})
            md.show_viewport = True            # in memory only: the scatter may be switched off for the viewport
        ob_.hide_viewport = False
for col in bpy.data.collections:
    if "scatter" in col.name.lower():
        diag.setdefault("_collections", []).append({"name": col.name, "hide_viewport": col.hide_viewport, "hide_render": col.hide_render, "objects": len(col.objects)})
print("SCAT modifiers", json.dumps(diag)[:1500], flush=True)
bpy.context.view_layer.update()
dg = bpy.context.evaluated_depsgraph_get(); dg.update()
by = {}
n_all = 0
parents = {}
for inst in dg.object_instances:
    if inst.is_instance and inst.parent is not None:
        parents[inst.parent.name] = parents.get(inst.parent.name, 0) + 1
    if not inst.is_instance or inst.parent is None or not inst.parent.name.startswith("Terrain"):
        continue
    ob = inst.object
    if ob.type != "MESH" or ob.data is None or ob.data.name.startswith("Terrain"):
        continue
    n_all += 1
    m = inst.matrix_world
    if bounds and not (bounds[0] <= m[0][3] <= bounds[2] and bounds[1] <= m[1][3] <= bounds[3]):
        continue
    key = (ob.data.name if ob.data else ob.name, inst.parent.name)      # geometry-nodes instances: the instanced mesh data
    by.setdefault(key, []).append([m[0][0], m[0][1], m[0][2], m[0][3], m[1][0], m[1][1], m[1][2], m[1][3], m[2][0], m[2][1], m[2][2], m[2][3]])
print("SCAT instance parents (top):", sorted(parents.items(), key=lambda kv: -kv[1])[:8], flush=True)
for tn in ("Terrain_Near", "Terrain_Far"):
    eo = bpy.data.objects[tn].evaluated_get(dg)
    try:
        em = eo.to_mesh()
        print("SCAT evaluated", tn, "verts", len(em.vertices), "polys", len(em.polygons), "base polys", len(bpy.data.objects[tn].data.polygons), flush=True)
        eo.to_mesh_clear()
    except Exception as e_:
        print("SCAT evaluated mesh failed", tn, e_)
info = []
for i, ((name, parent), mats) in enumerate(sorted(by.items(), key=lambda kv: -len(kv[1]))):
    me = bpy.data.meshes.get(name)
    if me is None:
        print("SCAT mesh data not found:", name); continue
    ob = next((o for o in bpy.data.objects if o.data == me), None)
    me.calc_loop_triangles()
    nl = len(me.loops); nv = len(me.vertices); nt = len(me.loop_triangles)
    pos = np.empty(nv * 3, np.float32); me.vertices.foreach_get("co", pos)
    lv = np.empty(nl, np.int32); me.loops.foreach_get("vertex_index", lv)
    ln = np.empty(nl * 3, np.float32)
    try:
        me.corner_normals.foreach_get("vector", ln)
    except Exception:
        me.loops.foreach_get("normal", ln)
    tl = np.empty(nt * 3, np.int32); me.loop_triangles.foreach_get("loops", tl)
    tm = np.empty(nt, np.int32); me.loop_triangles.foreach_get("material_index", tm)
    uv = np.zeros(nl * 2, np.float32)
    if me.uv_layers:
        me.uv_layers[0].data.foreach_get("uv", uv)
    np.savez(os.path.join(out, "scatter_mesh_%d.npz" % i), pos=pos.reshape(-1, 3), loop_vert=lv, loop_normal=ln.reshape(-1, 3), uv0=uv.reshape(-1, 2),
             tri_loops=tl.reshape(-1, 3), tri_mat=tm)
    np.save(os.path.join(out, "scatter_%d.npy" % i), np.array(mats, np.float32))
    info.append({"index": i, "object": name, "parent": parent, "mesh": me.name, "materials": [m.name if m else None for m in me.materials],
                 "tris": nt, "instances": len(mats)})
    print("SCAT %-40s on %-12s tris %5d instances %7d" % (name[:40], parent, nt, len(mats)), flush=True)
json.dump({"items": info, "instances_total": n_all, "bounds": bounds}, open(os.path.join(out, "scatter.json"), "w"), indent=1)
print("SCAT done: %d source objects, %d instances kept of %d" % (len(info), sum(x["instances"] for x in info), n_all))
